	/** 
	 * jumpstart the process by instantiating2 Branch
	 */
	protected void jumpStart() throws Throwable {
		LOGGER.info( "\n======== create instances to get the ball rolling  ======== ");

		branchId = BranchService.getBranchInstance()
		.createBranch( generateNewCommand() )
		.get();

		// ---------------------------------------------
		// set up query subscriptions after the 1st create
		// ---------------------------------------------
		testingStep = "create";
		setUpQuerySubscriptions();

		BranchService.getBranchInstance()
				.createBranch( generateNewCommand() )
				.get();

	}

	/** 
	 * Set up query subscriptions
	 */
	protected void setUpQuerySubscriptions() throws Throwable {
		LOGGER.info( "\n======== Setting Up Query Subscriptions ======== ");
			
		try {            
			subscriber.branchSubscribe().updates().subscribe(
					  successValue -> {
						  LOGGER.info(successValue.toString());
						  try {
							  LOGGER.info("GetAll update received for Branch : " + successValue.getBranchId());
							  if (successValue.getBranchId().equals(branchId)) {
								  if (testingStep.equals("create")) {
									  testingStep = "update";
									  update();
								  } else if (testingStep.equals("delete")) {
									  testingStep = "complete";
									  state( getAll().size() == sizeOfBranchList - 1 , "value not deleted from list");
									  LOGGER.info("**********************************************************");
									  LOGGER.info("Branch test completed successfully...");
									  LOGGER.info("**********************************************************\n");
								  }
							  }
						  } catch( Throwable exc ) {
							  LOGGER.warning( exc.getMessage() );
						  }
					  },
					  error -> LOGGER.warning(error.getMessage()),
					  () -> LOGGER.info("Subscription on branch consumed")
					);
			subscriber.branchSubscribe( branchId ).updates().subscribe(
					  successValue -> {
						  LOGGER.info(successValue.toString());
						  try {
							  LOGGER.info("GetOne update received for Branch : " + successValue.getBranchId() + " in step " + testingStep);
							  testingStep = "delete";
							  sizeOfBranchList = getAll().size();
							  delete();
						  } catch( Throwable exc ) {
							  LOGGER.warning( exc.getMessage() );
						  }
					  },
					  error -> LOGGER.warning(error.getMessage()),
					  () -> LOGGER.info("Subscription on branch for branchId consumed")

					);
			

			}
			catch (Exception e) {
				LOGGER.warning( e.getMessage() );
				throw e;
			}
		}
		
		/** 
	 * read a Branch. 
	 */
	protected Branch read() throws Throwable {
		LOGGER.info( "\n======== READ ======== ");
		LOGGER.info( "-- Reading a previously created Branch" );

		Branch entity = null;
		StringBuilder msg = new StringBuilder( "-- Failed to read Branch with primary key" );
		msg.append( branchId );
		
		BranchFetchOneSummary fetchOneSummary = new BranchFetchOneSummary( branchId );

		try {
			entity = BranchService.getBranchInstance().getBranch( fetchOneSummary );

			assertNotNull( entity,msg.toString() );

			LOGGER.info( "-- Successfully found Branch " + entity.toString() );
		}
		catch ( Throwable e ) {
			LOGGER.warning( unexpectedErrorMsg );
			LOGGER.warning( msg.toString() + " : " + e );

			throw e;
		}
		
		return entity;
	}

	/** 
	 * updating a Branch.
	 */
	protected void update() throws Throwable {
		LOGGER.info( "\n======== UPDATE ======== ");
		LOGGER.info( "-- Attempting to update a Branch." );

		StringBuilder msg = new StringBuilder( "Failed to update a Branch : " );        
		Branch entity = read();
		UpdateBranchCommand command = generateUpdateCommand();
		command.setBranchId(entity.getBranchId());

		try {            
			assertNotNull( entity, msg.toString() );

			LOGGER.info( "-- Now updating the created Branch." );

			// for use later on...
			branchId = entity.getBranchId();

			BranchService proxy = BranchService.getBranchInstance();  

			proxy.updateBranch( command ).get();

			LOGGER.info( "-- Successfully saved Branch - " + entity.toString() );
		}
		catch ( Throwable e ) {
			LOGGER.warning( unexpectedErrorMsg );
			LOGGER.warning( msg.toString() + " : primarykey = " + branchId + " : command -" +  command + " : " + e );

			throw e;
		}
	}

	/** 
	 * delete a Branch.
	 */
	protected void delete() throws Throwable {
		LOGGER.info( "\n======== DELETE ======== ");
		LOGGER.info( "-- Deleting a previously created Branch." );

		Branch entity = null;
		
		try{
		    entity = read(); 
			LOGGER.info( "-- Successfully read Branch with id " + branchId );            
		}
		catch ( Throwable e ) {
			LOGGER.warning( unexpectedErrorMsg );
			LOGGER.warning( "-- Failed to read Branch with id " + branchId );

			throw e;
		}

		try{
			BranchService.getBranchInstance().delete( new DeleteBranchCommand( entity.getBranchId() ) ).get();
			LOGGER.info( "-- Successfully deleted Branch with id " + branchId );            
		}
		catch ( Throwable e ) {
			LOGGER.warning( unexpectedErrorMsg );
			LOGGER.warning( "-- Failed to delete Branch with id " + branchId );

			throw e;
		}
	}

	/**
	 * get all Branchs.
	 */
	protected List<Branch> getAll() throws Throwable {    
		LOGGER.info( "======== GETALL ======== ");
		LOGGER.info( "-- Retrieving Collection of Branchs:" );

		StringBuilder msg = new StringBuilder( "-- Failed to get all Branch : " );        
		List<Branch> collection  = new ArrayList<>();

		try {
			// call the static get method on the BranchService
			collection = BranchService.getBranchInstance().getAllBranch();
			assertNotNull( collection, "An Empty collection of Branch was incorrectly returned.");
			
			// Now print out the values
			Branch entity = null;            
			Iterator<Branch> iter = collection.iterator();
			int index = 1;

			while( iter.hasNext() ) {
				// Retrieve the entity   
				entity = iter.next();

				assertNotNull( entity,"-- null entity in Collection." );
				assertNotNull( entity.getBranchId(), "-- entity in Collection has a null primary key" );        

				LOGGER.info( " - " + String.valueOf(index) + ". " + entity.toString() );
				index++;
			}
		}
		catch ( Throwable e ) {
			LOGGER.warning( unexpectedErrorMsg );
			LOGGER.warning( msg.toString() + " : " + e );

			throw e;
		}
		
		return collection;			
	}

